[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $ArtifactRoot,
    [Parameter(Mandatory)] [string] $OutputDirectory
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# Gate 0 proof infrastructure only. This runner does not participate in product
# import, persistence, rendering, UI, packaging, distribution, or cleanup.
$repositoryRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..')).TrimEnd([IO.Path]::DirectorySeparatorChar)
$approvedArtifactRoot = [IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetDirectoryName($repositoryRoot)) 'ReelForge.Gate0Artifacts')).TrimEnd([IO.Path]::DirectorySeparatorChar)
$contractPath = Join-Path $PSScriptRoot 'p3-jpeg-proof-contract.json'
$p2Validator = Join-Path $PSScriptRoot 'Validate-P2Runtime.ps1'
$retentionValidator = Join-Path $PSScriptRoot 'Test-Gate0ArtifactRetention.ps1'
$writer = Join-Path $PSScriptRoot 'Write-ExifOrientation.ps1'

function Get-Sha256([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Slash([string]$Path) { $Path.Replace('\', '/') }
function Value($Object, [string]$Name, $Default=$null) { $p=$Object.PSObject.Properties[$Name]; if($null -eq $p){$Default}else{$p.Value} }

function Assert-DirectNonReparseDirectory([string]$Path, [string]$Label, [bool]$MustExist=$true) {
    if (-not [IO.Path]::IsPathRooted($Path)) { throw "$Label must be an explicit rooted path." }
    $full=[IO.Path]::GetFullPath($Path).TrimEnd([IO.Path]::DirectorySeparatorChar)
    if($MustExist -and -not(Test-Path -LiteralPath $full -PathType Container)){throw "$Label does not exist or is not a directory: $full"}
    $parent=if(Test-Path -LiteralPath $full){$null}else{[IO.Path]::GetDirectoryName($full)}
    if($MustExist){$existing=Get-Item -LiteralPath $full -Force;if(($existing.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){throw "$Label is a reparse point: $($existing.FullName)"}}
    if($null -eq $parent){return $full}
    if([string]::IsNullOrWhiteSpace($parent)){throw "$Label has no physical parent."}
    $item=Get-Item -LiteralPath $parent -Force
    while($null -ne $item){if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){throw "$Label must not traverse a reparse-point ancestor: $($item.FullName)"};$item=$item.Parent}
    return $full
}

$resolvedArtifactRoot=Assert-DirectNonReparseDirectory $ArtifactRoot 'ArtifactRoot'
if(-not $resolvedArtifactRoot.Equals($approvedArtifactRoot,[StringComparison]::OrdinalIgnoreCase)){throw "ArtifactRoot must be the approved repository sibling: $approvedArtifactRoot"}
if(-not [IO.Path]::IsPathRooted($OutputDirectory)){throw 'OutputDirectory must be an explicit rooted path.'}
$resolvedOutput=[IO.Path]::GetFullPath($OutputDirectory).TrimEnd([IO.Path]::DirectorySeparatorChar)
if($resolvedOutput.Equals($repositoryRoot,[StringComparison]::OrdinalIgnoreCase) -or $resolvedOutput.StartsWith("$repositoryRoot\",[StringComparison]::OrdinalIgnoreCase)){throw 'Proof output must remain outside the repository.'}
if($resolvedOutput.Equals($resolvedArtifactRoot,[StringComparison]::OrdinalIgnoreCase) -or $resolvedOutput.StartsWith("$resolvedArtifactRoot\",[StringComparison]::OrdinalIgnoreCase)){throw 'Proof output must remain outside the retained corpus until it is separately manifested.'}
if(Test-Path -LiteralPath $resolvedOutput){throw 'Proof output must be a new directory.'}
[void](Assert-DirectNonReparseDirectory $resolvedOutput 'OutputDirectory' $false)
[IO.Directory]::CreateDirectory($resolvedOutput)|Out-Null
$created=Get-Item -LiteralPath $resolvedOutput -Force
if(($created.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Created OutputDirectory is a reparse point.'}
$media=Join-Path $resolvedOutput 'media';$logs=Join-Path $resolvedOutput 'logs';$work=Join-Path $resolvedOutput 'work'
@($media,$logs,$work)|ForEach-Object {[IO.Directory]::CreateDirectory($_)|Out-Null}
foreach($directory in @($media,$logs,$work)){[void](Assert-DirectNonReparseDirectory $directory 'Proof output child')}

$commands=[Collections.Generic.List[object]]::new();$cases=[Collections.Generic.List[object]]::new();$run=[ordered]@{status='started';startedAtUtc=[DateTimeOffset]::UtcNow;completedAtUtc=$null;error=$null;counts=$null}
function Artifact([string]$Path){$item=Get-Item -LiteralPath $Path -Force;$rel=[IO.Path]::GetRelativePath($resolvedOutput,$item.FullName);if([IO.Path]::IsPathRooted($rel)-or $rel.StartsWith('..')){throw "Output artifact escaped proof root: $Path"};[ordered]@{path=(Slash $rel);length=[int64]$item.Length;sha256=(Get-Sha256 $item.FullName)}}
function Assert-ExactNewMediaOutput([string]$Filename){
    if($Filename -notin 'progressive-420.jpg','baseline-420-orientation-6.jpg'){throw "Output filename is not an approved literal: $Filename"}
    $path=[IO.Path]::GetFullPath((Join-Path $media $Filename));$expected=[IO.Path]::GetFullPath((Join-Path $media $Filename))
    if(-not $path.Equals($expected,[StringComparison]::OrdinalIgnoreCase)-or -not $path.StartsWith("$media\",[StringComparison]::OrdinalIgnoreCase)){throw 'Approved output escaped the proof media directory.'}
    [void](Assert-DirectNonReparseDirectory $media 'Proof media directory')
    if(Test-Path -LiteralPath $path){throw "Approved output already exists: $Filename"};if(Test-Path -LiteralPath "$path.partial"){throw "Approved output partial already exists: $Filename.partial"};$path
}
function AtomicJson([string]$Path,$Object){$partial="$Path.partial";try{[IO.File]::WriteAllText($partial,($Object|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $partial -Destination $Path -Force}finally{if(Test-Path $partial){Remove-Item -LiteralPath $partial -Force}}}
function Retained([string]$Relative){$native=$Relative.Replace('/', '\');if([IO.Path]::IsPathRooted($native)-or $native.StartsWith('..')){throw "Unsafe retained path: $Relative"};$path=[IO.Path]::GetFullPath((Join-Path $resolvedArtifactRoot $native));if(-not $path.StartsWith("$resolvedArtifactRoot\",[StringComparison]::OrdinalIgnoreCase)-or -not(Test-Path -LiteralPath $path -PathType Leaf)){throw "Retained artifact missing or escaped root: $Relative"};$path}
function RetainedArtifact([string]$Relative){$path=Retained $Relative;$item=Get-Item -LiteralPath $path -Force;[ordered]@{path=(Slash $Relative);length=[int64]$item.Length;sha256=(Get-Sha256 $item.FullName)}}
function Recorded([string]$Name,[string]$Executable,[string[]]$Arguments,[string]$WorkingDirectory,[object]$Components){
    if($Name -notmatch '^[A-Za-z0-9_.-]+$'){throw "Unsafe command name: $Name"};$out=Join-Path $logs "$Name.stdout.txt";$err=Join-Path $logs "$Name.stderr.txt";$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$Executable;$si.WorkingDirectory=$WorkingDirectory;$si.UseShellExecute=$false;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
    # The exact executable is supplied directly. Its working directory and PATH are the retained P3 closure, never ambient tool discovery.
    $si.Environment['PATH']=$WorkingDirectory
    foreach($a in $Arguments){[void]$si.ArgumentList.Add($a)};$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$started=[DateTimeOffset]::UtcNow;if(-not $p.Start()){throw "Could not start command: $Name"};$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$p.WaitForExit();[IO.File]::WriteAllText($out,$ot.GetAwaiter().GetResult(),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($err,$et.GetAwaiter().GetResult(),[Text.UTF8Encoding]::new($false));$record=[ordered]@{name=$Name;executable=$Executable;arguments=$Arguments;workingDirectory=$WorkingDirectory;components=$Components;exitCode=$p.ExitCode;elapsedMilliseconds=([DateTimeOffset]::UtcNow-$started).TotalMilliseconds;stdout=(Artifact $out);stderr=(Artifact $err)};$commands.Add($record);$record
}
function RequireSuccess($Record,[string]$Purpose){if($Record.exitCode-ne 0){throw "$Purpose failed with exit code $($Record.exitCode)."}}
function ParsePpm([string]$Path){$b=[IO.File]::ReadAllBytes($Path);$tokens=[Collections.Generic.List[string]]::new();$i=0;while($tokens.Count-lt 4 -and $i-lt $b.Length){while($i-lt $b.Length -and [char]$b[$i]-match '\s'){$i++};if($i-lt $b.Length -and $b[$i]-eq 35){while($i-lt $b.Length -and $b[$i]-notin 10,13){$i++};continue};$s=$i;while($i-lt $b.Length -and [char]$b[$i]-notmatch '\s'){$i++};if($i-gt $s){$tokens.Add([Text.Encoding]::ASCII.GetString($b,$s,$i-$s))}};if(@($tokens).Count-ne 4-or $tokens[0]-ne 'P6'-or $tokens[3]-ne '255'){throw 'Source PPM is not a bounded P6 8-bit fixture.'};while($i-lt $b.Length -and [char]$b[$i]-match '\s'){$i++};$pixels=[byte[]]::new($b.Length-$i);[Array]::Copy($b,$i,$pixels,0,$pixels.Length);[ordered]@{width=[int]$tokens[1];height=[int]$tokens[2];pixels=$pixels}}
function Mae([byte[]]$A,[byte[]]$B){if($A.Length-ne $B.Length){throw 'Visual oracle rasters have unequal lengths.'};[double]$sum=0;for($i=0;$i-lt $A.Length;$i++){$sum+=[Math]::Abs([int]$A[$i]-[int]$B[$i])};$sum/$A.Length}
function RotateCw([byte[]]$Source,[int]$Width,[int]$Height){$o=[byte[]]::new($Source.Length);for($y=0;$y-lt $Height;$y++){for($x=0;$x-lt $Width;$x++){$src=($y*$Width+$x)*3;$dx=$Height-1-$y;$dy=$x;$dst=($dy*$Height+$dx)*3;[Array]::Copy($Source,$src,$o,$dst,3)}};$o}
function Same([byte[]]$A,[byte[]]$B){$A.Length-eq $B.Length -and [Security.Cryptography.CryptographicOperations]::FixedTimeEquals($A,$B)}
function Read-SofStructure([string]$Path){
    $b=[IO.File]::ReadAllBytes($Path);if($b.Length-lt 4-or$b[0]-ne 0xFF-or$b[1]-ne 0xD8){throw 'JPEG SOI is missing.'}
    $sofs=[Collections.Generic.List[object]]::new();$i=2
    while($i+1-lt $b.Length){
        if($b[$i]-ne 0xFF){throw 'JPEG marker framing is invalid before SOS.'};while($i-lt $b.Length-and$b[$i]-eq 0xFF){$i++};if($i-ge $b.Length){throw 'Truncated JPEG marker.'};$m=$b[$i];$i++
        if($m-eq 0xDA){break};if($m-eq 0xD9){break};if($m-in 0xD8,0x01-or($m-ge 0xD0-and$m-le 0xD7)){continue};if($i+1-ge $b.Length){throw 'Truncated JPEG segment length.'}
        $len=($b[$i]*256)+$b[$i+1];if($len-lt 2-or $i+$len-gt $b.Length){throw 'Invalid JPEG segment length.'}
        if(($m-ge 0xC0-and$m-le 0xCF)-and$m-notin 0xC4,0xC8,0xCC){
            if($len-lt 8){throw 'JPEG SOF segment is too short.'};$precision=[int]$b[$i+2];$height=([int]$b[$i+3]*256)+$b[$i+4];$width=([int]$b[$i+5]*256)+$b[$i+6];$count=[int]$b[$i+7]
            if($len-ne(8+(3*$count))){throw 'JPEG SOF segment length does not match component count.'};$components=[Collections.Generic.List[object]]::new()
            for($c=0;$c-lt $count;$c++){$p=$i+8+(3*$c);$sampling=[int]$b[$p+1];$components.Add([ordered]@{id=[int]$b[$p];horizontalSampling=($sampling -shr 4);verticalSampling=($sampling -band 0x0F);quantizationTable=[int]$b[$p+2]})}
            $sofs.Add([ordered]@{marker=('C{0:X1}' -f ($m-0xC0));precision=$precision;width=$width;height=$height;componentCount=$count;components=@($components)})
        };$i+=$len
    };@($sofs)
}
function Assert-ExactProgressive420Sof($Sofs,$Required){
    if(@($Sofs).Count-ne 1){throw 'Progressive JPEG must contain exactly one SOF segment.'};$sof=$Sofs[0]
    if($sof.marker-ne [string]$Required.marker-or$sof.precision-ne [int]$Required.precision-or$sof.componentCount-ne 3){throw 'Progressive JPEG SOF does not equal the approved C2, 8-bit, three-component structure.'}
    $expected=@($Required.components);for($i=0;$i-lt 3;$i++){$actual=$sof.components[$i];$want=$expected[$i];if($actual.id-ne[int]$want.id-or$actual.horizontalSampling-ne[int]$want.horizontalSampling-or$actual.verticalSampling-ne[int]$want.verticalSampling){throw 'Progressive JPEG SOF component identities or sampling factors do not equal approved 4:2:0.'}}
    $sof
}
function ReadOrientation([string]$Path){$b=[IO.File]::ReadAllBytes($Path);$expected=[byte[]]@(0xFF,0xE1,0x00,0x22,0x45,0x78,0x69,0x66,0x00,0x00,0x49,0x49,0x2A,0x00,0x08,0x00,0x00,0x00,0x01,0x00,0x12,0x01,0x03,0x00,0x01,0x00,0x00,0x00,0x06,0x00,0x00,0x00,0x00,0x00,0x00,0x00);if($b.Length-lt $expected.Length+2-or$b[0]-ne 0xFF-or$b[1]-ne 0xD8){throw 'EXIF output lacks SOI.'};for($i=0;$i-lt $expected.Length;$i++){if($b[$i+2]-ne $expected[$i]){throw 'EXIF output does not contain exactly the approved minimal APP1/TIFF orientation=6 segment after SOI.'}};[ordered]@{orientation=6;app1Length=36;placement='immediately after SOI'}}
function Decode([string]$Name,[string]$Input,[bool]$Autorotate,[int]$Width,[int]$Height){$out=Join-Path $work "$Name.rgb24";$a=@('-hide_banner','-xerror','-err_detect','explode');if(-not $Autorotate){$a+=@('-noautorotate')};$a+=@('-f','image2','-c:v','mjpeg','-i',$Input,'-map','0:v:0','-frames:v','1','-c:v','rawvideo','-pix_fmt','rgb24','-f','rawvideo','-y',$out);$r=Recorded $Name $ffmpeg $a $p2Bin ([ordered]@{purpose='strict native P2 mjpeg decode';inputDemuxer='image2';inputDecoder='mjpeg';streamSelector='0:v:0';autorotate=$Autorotate;outputEncoder='rawvideo';outputMuxer='rawvideo'});RequireSuccess $r 'Strict native P2 image decode';$bytes=[IO.File]::ReadAllBytes($out);if($bytes.Length-ne($Width*$Height*3)){throw "Decoded raster does not have expected $Width x $Height rgb24 geometry."};[ordered]@{command=$r;artifact=(Artifact $out);bytes=$bytes;width=$Width;height=$Height}}
function Inspect([string]$Name,[string]$Input){$r=Recorded $Name $ffprobe @('-v','error','-f','image2','-show_streams','-show_frames','-show_packets','-show_data_hash','sha256','-of','json',$Input) $p2Bin ([ordered]@{purpose='explicit image2 inspection';inputDemuxer='image2';inputDecoder='mjpeg';allStreams=$true;allFrames=$true;allPackets=$true;packetDataHash='sha256'});RequireSuccess $r 'Explicit image2 inspection';$j=(Get-Content -LiteralPath (Join-Path $logs "$Name.stdout.txt") -Raw|ConvertFrom-Json -Depth 30);$allStreams=@(Value $j 'streams' @());$frames=@(Value $j 'frames' @());$packets=@(Value $j 'packets' @());if($allStreams.Count-ne 1-or$allStreams[0].codec_type-ne'video'-or$allStreams[0].codec_name-ne'mjpeg'-or$frames.Count-ne 1-or$packets.Count-ne 1-or(@($packets|Where-Object {[string]::IsNullOrWhiteSpace([string]$_.data_hash)}).Count-ne 0)){throw 'Inspection must provide exactly one mjpeg image stream, frame, packet, and a data hash for every packet.'};[ordered]@{command=$r;codec=[string]$allStreams[0].codec_name;width=[int]$allStreams[0].width;height=[int]$allStreams[0].height;streamCount=$allStreams.Count;frameCount=$frames.Count;packetCount=$packets.Count;stream=$allStreams[0];frame=$frames[0];packet=$packets[0];packetDataHashes=@($packets|ForEach-Object {[string]$_.data_hash})}}
function WriteEvidence {
    $generated=@(Get-ChildItem -LiteralPath $resolvedOutput -File -Recurse|Sort-Object FullName|ForEach-Object {Artifact $_.FullName})
    $contractEvidence=if($null-ne $contract){[ordered]@{path='eng/gate0/p3-jpeg-proof-contract.json';sha256=(Get-Sha256 $contractPath)}}else{$null}
    AtomicJson (Join-Path $resolvedOutput 'p3-jpeg-input-proof-evidence.json') ([ordered]@{schemaVersion=1;proofId=$(if($null-ne $contract){$contract.proofId}else{'not-loaded'});statement=$(if($null-ne $contract){$contract.statement}else{'Contract did not load; no proof conclusion is made.'});contract=$contractEvidence;run=$run;runtimeIdentity=$runtimeEvidence;producerClosure=$producerEvidence;commands=@($commands);cases=@($cases);generatedArtifactClosure=$generated;limitations=@('Proof infrastructure only; no shipping-runtime, product, bundling, redistribution, public-distribution, legal, or cleanup conclusion is made.','A retained local artifact root is one copy only and is not a production artifact repository.')})
}

$failure=$null;$runtimeEvidence=$null;$producerEvidence=$null;$contract=$null;$semantic=@{};$sharedFailure=$null
function CaseArtifact([string]$Filename){$candidate=Join-Path $media $Filename;$partial="$candidate.partial";if(Test-Path -LiteralPath $candidate -PathType Leaf){Artifact $candidate}elseif(Test-Path -LiteralPath $partial -PathType Leaf){Artifact $partial}else{$null}}
try {
    $contract=Get-Content -LiteralPath $contractPath -Raw|ConvertFrom-Json -Depth 30
    if(@($contract.cases).Count-ne 2 -or (@($contract.cases|ForEach-Object id)-join ',') -ne 'I-JPEG-PROGRESSIVE-420,I-JPEG-EXIF-ORIENTATION'){throw 'P3 JPEG proof contract must contain exactly the approved two rows in dependency order.'}
    & $retentionValidator -ArtifactRoot $resolvedArtifactRoot
    $manifestPath=Join-Path $repositoryRoot 'eng/gate0/artifact-retention-manifest.json';$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json -Depth 100;$p3=$contract.profiles.p3;$group=@($manifest.groups|Where-Object groupId -eq $p3.retentionGroupId);if($group.Count-ne 1){throw 'Retained manifest does not contain exactly the approved P3 group.'};$group=$group[0]
    if(@($group.producerRuntimeIdentity|Where-Object {$_ -eq "upstream:$($p3.upstreamRelease)"}).Count-ne 1-or @($group.producerRuntimeIdentity|Where-Object {$_ -eq 'manifest:p3Authenticode'}).Count-ne 1){throw 'P3 retained group does not bind approved upstream provenance and Authenticode identity.'}
    foreach($license in @($p3.licenseRelativePaths)){if(@($group.licenseRecords|Where-Object {$_ -eq "artifact:$license"}).Count-ne 1){throw "P3 retained group lacks approved license reference: $license"};[void](Retained $license)}
    $installer=@($group.files|Where-Object filename -eq $p3.installerRelativePath);if($installer.Count-ne 1-or [string]$installer[0].sha256-ne [string]$p3.installerSha256-or [int64]$installer[0].size-ne [int64]$p3.installerSize){throw 'P3 retained installer identity does not equal the approved contract.'};$installerPath=Retained $p3.installerRelativePath;if((Get-Sha256 $installerPath)-ne [string]$p3.installerSha256-or [int64](Get-Item $installerPath).Length-ne [int64]$p3.installerSize){throw 'P3 retained installer bytes do not equal approved identity.'}
    foreach($name in 'status','signerSubject','signerThumbprint','timestampSubject','timestampThumbprint'){if([string](Value $manifest.p3Authenticode $name)-ne [string](Value $p3.authenticode $name)){throw "P3 Authenticode $name does not equal approved identity."}}
    $p2Root=Assert-DirectNonReparseDirectory (Join-Path $resolvedArtifactRoot $contract.profiles.p2.runtimeRelativePath) 'Retained P2 runtime';$p2Bin=Assert-DirectNonReparseDirectory (Join-Path $p2Root 'bin') 'Retained P2 bin';$ffmpeg=Retained "$($contract.profiles.p2.runtimeRelativePath)/bin/ffmpeg.exe";$ffprobe=Retained "$($contract.profiles.p2.runtimeRelativePath)/bin/ffprobe.exe";$runtimeIdentity=Join-Path $resolvedOutput 'runtime-identity.json';& $p2Validator -RuntimeRoot $p2Root -EvidencePath $runtimeIdentity;if(-not(Test-Path -LiteralPath $runtimeIdentity -PathType Leaf)){throw 'Exact P2 runtime validation did not produce identity evidence.'};$runtimeEvidence=[ordered]@{evidence=(Artifact $runtimeIdentity);profileId=$contract.profiles.p2.profileId}
    $p3Bin=Assert-DirectNonReparseDirectory (Join-Path $resolvedArtifactRoot $p3.binRelativePath) 'Retained P3 bin';$cjpeg=Retained "$($p3.binRelativePath)/$($p3.cjpegRelativePath)";$closure=[Collections.Generic.List[object]]::new();foreach($entry in @($p3.closure)){$rel=[string]$entry.relativePath;$p=Retained "$($p3.binRelativePath)/$rel";$actualHash=Get-Sha256 $p;$actualSize=[int64](Get-Item $p).Length;if($actualHash-ne [string]$entry.sha256-or$actualSize-ne [int64]$entry.size){throw "Pinned P3 closure identity mismatch: $rel"};$closure.Add([ordered]@{path=(Slash $rel);sha256=$actualHash;length=$actualSize})};$producerEvidence=[ordered]@{profileId=$p3.profileId;role=$p3.role;retentionGroupId=$group.groupId;installer=[ordered]@{artifact=(RetainedArtifact $p3.installerRelativePath);approvedSha256=$p3.installerSha256;approvedSize=$p3.installerSize};authenticode=$manifest.p3Authenticode;upstreamRelease=$p3.upstreamRelease;licenseRecords=@($p3.licenseRelativePaths);workingDirectory=$p3Bin;closure=@($closure)}
    $source=Retained $contract.source.ppmRelativePath;if((Get-Sha256 $source)-ne $contract.source.ppmSha256){throw 'Pinned source PPM hash mismatch.'};$ppm=ParsePpm $source;if($ppm.width-ne $contract.source.width-or$ppm.height-ne $contract.source.height-or$ppm.pixels.Length-ne($ppm.width*$ppm.height*3)){throw 'Pinned source PPM geometry or raster is invalid.'};$version=Recorded 'p3-cjpeg-version' $cjpeg @('-version') $p3Bin ([ordered]@{purpose='explicit retained P3 cjpeg version evidence';producer='cjpeg';producerEvidence=$producerEvidence});RequireSuccess $version 'P3 cjpeg version preflight'
} catch {$sharedFailure=$_.Exception.Message}
if($null-ne $sharedFailure){$run.status='shared-preflight-blocked';$run.error=$sharedFailure;if($null-ne $contract){foreach($case in @($contract.cases)){$cases.Add([ordered]@{id=$case.id;status='blocked';execution='not-run-shared-preflight';reason=$sharedFailure;artifact=(CaseArtifact $case.output);executedSemanticProof=$false;contractWasNotWeakened=$true})}}}
else {
    $progressive=$contract.cases|Where-Object id -eq 'I-JPEG-PROGRESSIVE-420';try {$progressivePath=Assert-ExactNewMediaOutput $progressive.output;$progressivePartial="$progressivePath.partial";if((@($progressive.commandArguments)-join ' ') -ne '-quality 90 -dct int -progressive -sample 2x2,1x1,1x1'){throw 'Progressive JPEG command options do not equal the approved bounded options.'};$cmd=Recorded 'p3-cjpeg-progressive-420' $cjpeg (@($progressive.commandArguments)+@('-outfile',$progressivePartial,$source)) $p3Bin ([ordered]@{purpose='P3 fixture-production-only progressive 4:2:0 JPEG';producer='cjpeg';explicitOptions=@($progressive.commandArguments);producerEvidence=$producerEvidence;atomicOutput=$true});RequireSuccess $cmd 'P3 cjpeg progressive fixture authoring';if(-not(Test-Path -LiteralPath $progressivePartial -PathType Leaf)){throw 'P3 cjpeg did not create the progressive partial fixture.'};$sof=Assert-ExactProgressive420Sof (Read-SofStructure $progressivePartial) $progressive.requiredSof;Move-Item -LiteralPath $progressivePartial -Destination $progressivePath -ErrorAction Stop;$inspect=Inspect 'inspect-progressive-420' $progressivePath;$semantic[$progressive.id]=$true;if($inspect.width-ne 320-or$inspect.height-ne 180){throw 'Progressive JPEG geometry is not 320x180.'};$decoded=Decode 'decode-progressive-420-noautorotate' $progressivePath $false 320 180;$mae=Mae $ppm.pixels $decoded.bytes;if($mae-gt [double]$contract.oracles.jpegVisual.maximumMeanAbsoluteError){throw "Progressive JPEG visual oracle failed: MAE $mae exceeds contract."};$cases.Add([ordered]@{id=$progressive.id;status='passed';artifact=(Artifact $progressivePath);producerVersionCommand=$version;producerCommand=$cmd;sof=$sof;inspection=$inspect;nativeDecode=[ordered]@{artifact=$decoded.artifact;meanAbsoluteError=$mae;maximumMeanAbsoluteError=$contract.oracles.jpegVisual.maximumMeanAbsoluteError;passed=$true};executedSemanticProof=$true})} catch {$cases.Add([ordered]@{id=$progressive.id;status='failed';reason=$_.Exception.Message;artifact=(CaseArtifact $progressive.output);commandCount=$commands.Count;executedSemanticProof=($semantic[$progressive.id] -eq $true);contractWasNotWeakened=$true})}
    $orientation=$contract.cases|Where-Object id -eq 'I-JPEG-EXIF-ORIENTATION';try {$baseline=Retained $orientation.baselineRelativePath;if((Get-Sha256 $baseline)-ne $orientation.baselineSha256){throw 'Pinned baseline 4:2:0 JPEG hash mismatch.'};$orientationPath=Assert-ExactNewMediaOutput $orientation.output;$writerOutput=Join-Path $logs 'write-exif-orientation-6.operation.json';$writerJson=& $writer -InputJpeg $baseline -OutputJpeg $orientationPath -ExpectedInputSha256 $orientation.baselineSha256 -Orientation 6;if(-not(Test-Path -LiteralPath $orientationPath -PathType Leaf)){throw 'Repository-owned EXIF writer did not create its output.'};[IO.File]::WriteAllText($writerOutput,$writerJson,[Text.UTF8Encoding]::new($false));$writerRecord=[ordered]@{name='write-exif-orientation-6';operation='in-process repository-owned byte writer';script=[ordered]@{path='eng/gate0/Write-ExifOrientation.ps1';sha256=(Get-Sha256 $writer)};arguments=@('-InputJpeg',$baseline,'-OutputJpeg',$orientationPath,'-ExpectedInputSha256',$orientation.baselineSha256,'-Orientation','6');components=[ordered]@{purpose='repository-owned deterministic minimal APP1/TIFF orientation writer';inputHash=$orientation.baselineSha256;orientation=6;noImageEncoder=$true};operationEvidence=(Artifact $writerOutput)};$commands.Add($writerRecord);$tag=ReadOrientation $orientationPath;$baselineBytes=[IO.File]::ReadAllBytes($baseline);$orientationBytes=[IO.File]::ReadAllBytes($orientationPath);if($orientationBytes.Length-ne($baselineBytes.Length+36)){throw 'EXIF writer changed JPEG bytes beyond the one APP1 segment.'};for($i=0;$i-lt $baselineBytes.Length-2;$i++){if($orientationBytes[$i+38]-ne $baselineBytes[$i+2]){throw 'EXIF writer did not preserve every baseline byte after SOI.'}};$inspectO=Inspect 'inspect-orientation-6' $orientationPath;$semantic[$orientation.id]=$true;if($inspectO.width-ne 320-or$inspectO.height-ne 180){throw 'Orientation JPEG encoded geometry is not 320x180.'};$baseDecode=Decode 'decode-baseline-42